{"implementation":"def solve(case):
    nodes = list(case.get("nodes", []))
    core = case.get("core_distance", {})
    order = {node: index for index, node in enumerate(nodes)}
    edges = []

    for item in case.get("distances", []):
        left, right, distance = item
        weight = max(core[left], core[right], distance)
        left_index = order.get(left, len(order))
        right_index = order.get(right, len(order))
        if left_index > right_index:
            left, right = right, left
            left_index, right_index = right_index, left_index
        edges.append((weight, left_index, right_index, left, right))

    edges.sort(key=lambda edge: (edge[0], edge[1], edge[2]))
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    def union(left, right):
        left_root = find(left)
        right_root = find(right)
        if left_root == right_root:
            return False
        if rank[left_root] < rank[right_root]:
            left_root, right_root = right_root, left_root
        parent[right_root] = left_root
        if rank[left_root] == rank[right_root]:
            rank[left_root] += 1
        return True

    mst_edges = []
    for weight, _, _, left, right in edges:
        if union(left, right):
            mst_edges.append([left, right, weight])
            if len(mst_edges) == max(0, len(nodes) - 1):
                break

    return {"mst_edges": mst_edges}
